from qiskit import QuantumCircuit

def convert_quantum_circuit_to_qasm_string(circuit):
    """
    Convert a QuantumCircuit to an OpenQASM 2.0 string.

    Args:
        circuit: A Qiskit QuantumCircuit object to be converted

    Returns:
        str: The OpenQASM 2.0 representation of the circuit

    Example:
        >>> from qiskit import QuantumCircuit
        >>> qc = QuantumCircuit(2)
        >>> qc.h(0)
        >>> qc.cx(0, 1)
        >>> qasm_str = convert_quantum_circuit_to_qasm_string(qc)
        >>> print(qasm_str)
        OPENQASM 2.0;
        include "qelib1.inc";
        qreg q[2];
        h q[0];
        cx q[0],q[1];
    """
    return circuit.qasm()

def qubit_with_least_readout_error(backend):
    """
    Return the minimum readout error across all qubits in the backend.

    Args:
        backend: A FakeBackendV2 or IBMBackend instance

    Returns:
        float: The minimum readout error value, or None if not available
    """
    # Retrieve backend properties
    try:
        props = backend.properties()
    except (AttributeError, TypeError):
        return None

    if props is None:
        return None

    min_error = float('inf')

    # Iterate through all qubits to find readout errors
    for qubit_props in props.qubits:
        for prop in qubit_props:
            if prop.name == 'readout_error':
                error_value = prop.value
                if error_value is not None and error_value < min_error:
                    min_error = error_value
                break

    return min_error if min_error != float('inf') else None
